        if (Math.abs(uv) <= 1e-14 * (Math.abs(a[0]) + Math.abs(a[4]) + Math.abs(a[8]))) break;
        const angle = 0.5 * Math.atan2(2 * uv, a[v * 3 + v] - a[u * 3 + u]);
